        String sourcePartition = getPartition(edge.getSourceVertex());
        String targetPartition = getPartition(edge.getTargetVertex());
        if (!edgeMap.containsKey(sourcePartition)) {
            edgeMap.put(sourcePartition, new ArrayList<>());
        }
        edgeMap.get(sourcePartition).add(edge);

        if (!edgeMap.containsKey(targetPartition)) {
            edgeMap.put(targetPartition, new ArrayList<>());
        }
        edgeMap.get(targetPartition).add(edge);
    }

    // create a new graph with the same vertices and edges as the original graph
    Graph<V,E> completeGraph = new Graph<>(target.getVertices(), target.getEdges());

    // add new vertices and edges to the complete graph
    for (String partition : partitionMap.keySet()) {
        for (V vertex : partitionMap.get(partition)) {
            for (E edge : edgeMap.get(partition)) {
                if (!completeGraph.hasVertex(edge.getTargetVertex())) {
                    completeGraph.addVertex(edge.getTargetVertex());
                }
                if (completeGraph.hasEdge(edge.getSourceVertex(), edge.getTargetVertex())) {
                    throw new IllegalArgumentException("The graph is not bipartite");
                }
                completeGraph.addEdge(edge.getSourceVertex(), edge.getTargetVertex());
            }
        }
    }

    // remove excess edges
    for (E edge : completeGraph.getEdges()) {
        if (edgeMap.containsKey(edge.getSourceVertex()) && edgeMap.containsKey(edge.getTargetVertex())) {
