public List<SequenceRange> buildSequenceRanges(List<Profile> profiles, Integer segmentation_window, Integer chunk_window) {
    // Input validation
    if (profiles == null || profiles.isEmpty()) {
        throw new IllegalArgumentException("Profiles list is null or empty");
    }
    if (segmentation_window == null || segmentation_window <= 0) {
        throw new IllegalArgumentException("Segmentation window must be a positive integer");
    }
    if (chunk_window == null || chunk_window <= 0) {
        throw new IllegalArgumentException("Chunk window must be a positive integer");
    }

    // Calculate the total duration of the profiles
    long totalDuration = 0;
    for (Profile profile : profiles) {
        totalDuration += profile.getDuration();
    }

    // Determine the number of segments and chunks
    int numSegments = (int) Math.ceil((float) totalDuration / (float) segmentation_window);
    int numChunks = (int) Math.ceil((float) totalDuration / (float) chunk_window);

    // Create a list to store the sequence ranges
    List<SequenceRange> sequenceRanges = new ArrayList<>();

    // Iterate over each profile and add the sequence ranges to the list
    for (Profile profile : profiles) {
        long profileDuration = profile.getDuration();
        int profileStart = 0;
        while (profileStart < profileDuration) {
            int chunkStart = Math.max(profileStart, chunk_window - 1);
            int chunkEnd = Math.min(profileStart + chunk_window, profileDuration);
            int segmentStart = Math.max(chunkStart, segmentation_window - 1);
            int segmentEnd = Math.min(chunkEnd, segmentation_window);
