public Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
  if (bounds == null || bounds.isEmpty()) {
    throw new IllegalArgumentException("Invalid input: bounds must be a non-empty list of integers");
  }

  int n = bounds.size();
  long[] suffixSum = new long[n];

  // Compute the suffix sum for each element in the list
  for (int i = n - 1; i >= 0; i--) {
    suffixSum[i] = bounds.get(i);
    if (i > 0) {
      suffixSum[i - 1] += suffixSum[i];
    }
  }

  // Compute the sum of all elements in the list
  long sum = 0;
  for (int i = 0; i < n; i++) {
    sum += suffixSum[i];
  }

  List<Integer> suffixSumList = new ArrayList<>();
  for (int i = 0; i < n; i++) {
    suffixSumList.add(suffixSum[i]);
  }

  return new Pair<>(suffixSumList, sum);
}

