 * @return a two element array with index 0 being before the delimiter, and index 1 being after the delimiter (neither element includes the delimiter); or null if the delimiter wasn't found in the given input String
 */
public static String[] split(String toSplit, String delimiter) {
    if (toSplit == null || delimiter == null) {
        throw new IllegalArgumentException("Input string or delimiter cannot be null");
    }

    int index = toSplit.indexOf(delimiter);
    if (index == -1) {
        return null;
    }

    String beforeDelimiter = toSplit.substring(0, index);
    String afterDelimiter = toSplit.substring(index + delimiter.length());

    return new String[] { beforeDelimiter, afterDelimiter };
