private String buildContentRange() {
    // Retrieve the 'Range' header value from the request
    String range = getRequest().getHeader("Range");

    // Parse the 'Range' header value to extract the start and end offsets
    int startOffset = Integer.parseInt(range.substring(0, range.indexOf("-")));
    int endOffset = Integer.parseInt(range.substring(range.indexOf("-") + 1));

    // Calculate the length of the content range
    int contentLength = endOffset - startOffset + 1;

    // Build the 'Content-Range' header value
    String contentRange = "bytes " + startOffset + "-" + endOffset + "/" + contentLength;

    return contentRange;
}

