public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

// Step 1: Read file contents
String fileContents = new String(Files.readAllBytes(file.toPath()));

// Step 2: Extract thread snapshots from file contents
List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
Pattern threadSnapshotPattern = Pattern.compile("^\s*-+\s*Snapshot\s*-\s*(\d+)\s*\( (\w+) \s*\)");
Matcher threadSnapshotMatcher = threadSnapshotPattern.matcher(fileContents);
while (threadSnapshotMatcher.find()) {
String snapshotId = threadSnapshotMatcher.group(1);
String snapshotSource = threadSnapshotMatcher.group(2);

// Step 3: Extract stack trace from thread snapshot
Pattern stackTracePattern = Pattern.compile("^(\s*)Stack:\s*(.*)$", Pattern.MULTILINE);
Matcher stackTraceMatcher = stackTracePattern.matcher(fileContents);
if (stackTraceMatcher.find()) {
String stackTrace = stackTraceMatcher.group(2);

// Step 4: Extract thread information from stack trace
Map<String, String> threadInfo = new LinkedHashMap<>();
Pattern threadInfoPattern = Pattern.compile("^(\w+)\(([\w.$]+)\)");
Matcher threadInfoMatcher = threadInfoPattern.matcher(stackTrace);
while (threadInfoMatcher.find()) {
String threadName = threadInfoMatcher.group(1);
String threadId = threadInfoMatcher.group(2);
threadInfo.put(threadName, threadId);
}

// Step 5: Filter thread snapshots based on time range
boolean isSnapshotInRange = false;
for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
if (timeRange.contains(Long.parseLong(snapshotId))) {
isSnapshotInRange = true;
break;
}
}

// Step 6: Add thread snapshot to list
if (isSnapshotInRange) {
ThreadSnapshot snapshot = new ThreadSnapshot(snapshotId, snapshotSource, threadInfo);
threadSnapshots.add(snapshot);
}
}
}

return threadSnapshots;
}

public static class ThreadSnapshot {
private String id;
private String source;
private List<String> frames;

public ThreadSnapshot(String id, String source, Map<String, String> threadInfo) {
this.id = id;
this.source = source;
this.frames = new ArrayList<>();

for (Map.Entry<String, String> entry : threadInfo.entrySet()) {
String key = entry.getKey();
String value = entry.getValue();
frames.add(String.format("%s: %s", key, value));
}
}

public String getId() {
return id;
}

public String getSource() {
return source;
}

public List<String> getFrames() {
return frames;
}
}

public static class ProfileAnalyzeTimeRange {
private long start;
private long end;

public ProfileAnalyzeTimeRange(long start, long end) {
this.start = start;
this.end = end;
}

public boolean contains(long time) {
return time >= start && time <= end;
}
}

